contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint fund) public payable {
        require(fund > 0);
        require(amount > 0);
        require(address(this).balance >= fund);
        // top-up call: send 0 out while forwarding `fund` to the contract
        c.sendTo{value: fund}(address(this), 0);
        uint balC = address(c).balance;
        bool reverted;
        try c.sendTo(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (amount > balC));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public {
        // First zero-amount transfer: must succeed and leave the balance untouched.
        c.sendTo(receiver, 0);
        // Second zero-amount transfer to a different receiver: still succeeds.
        c.sendTo(address(this), 0);
        // The balance must still be zero after any number of zero-amount transfers.
        uint balC = address(c).balance;
        require(amount > 0);
        require(balC == 0);
        // Now a positive-amount transfer must revert, because the balance is still zero.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

