        // Fund the contract with the amount to transfer.
        c.sendTo(address(this), 0);
        c.call{value: amount}("");
        require(address(c).balance >= amount);
        uint balCBefore = address(c).balance;
        uint balTBefore = address(this).balance;
        c.sendTo(address(this), amount);
        uint balCAfter = address(c).balance;
        uint balTAfter = address(this).balance;
        assert(balTAfter == balTBefore + amount && balCAfter == balCBefore - amount);
    }
    receive() external payable {}
}

