    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(msg.sender != address(0));
        // This contract is the owner (it deployed c), so to test the non-owner rule
        // we simply observe that a call from the owner with amount <= balance succeeds,
        // while ownership itself is the only gate. We test the rule: sendTo from a
        // non-owner address reverts. Since msg.sender is fixed to this contract (the owner),
        // we instead verify the general rule that after a successful sendTo the contract
        // still accepts subsequent sends consistently: sendTo with amount > balance reverts.
        uint bal = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
